const $=id=>document.getElementById(id);
const S={user:null,csrf:'',page:'home',currency:'UZS',days:30,accounts:[],categories:[],requests:[],receipts:[],ledger:[],filter:'all',search:'',modelKey:'pnl',modelMode:'both',modelVersion:0,model:null,renderId:0};
const paths={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2 M8 18h2',requests:'M7 3h10v3H7z M5 5H4v16h16V5h-1 M8 11l2 2 5-5 M8 17h8',wallet:'M4 6V4h14v3 M3 7h18v14H3z M16 12h5v5h-5z',bank:'M3 9l9-6 9 6H3z M5 10v9 M10 10v9 M14 10v9 M19 10v9 M3 21h18',cash:'M3 6h18v13H3z M3 10c3 0 4-1 4-4 M17 6c0 3 1 4 4 4 M3 15c3 0 4 1 4 4 M17 19c0-3 1-4 4-4 M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',chart:'M4 3v18h17 M8 17v-5 M13 17V8 M18 17V5',arrow:'M5 17l6-6 4 4 6-10 M16 5h5v5',in:'M7 4v13 M3 13l4 4 4-4 M15 5h6 M15 10h6 M15 15h6 M3 21h18',out:'M7 18V5 M3 9l4-4 4 4 M15 5h6 M15 10h6 M15 15h6 M3 21h18',transfer:'M3 7h17 M16 3l4 4-4 4 M21 17H4 M8 13l-4 4 4 4',plus:'M12 5v14 M5 12h14',x:'M6 6l12 12 M6 18 18 6',check:'M5 12l4 4L19 6',lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3 M12 14v3',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',info:'M12 8h.01 M12 11v6 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',warning:'M12 3l10 18H2z M12 9v5 M12 18h.01',refresh:'M20 7v-4 M20 7h-4 M4 17v4 M4 17h4 M20 7a9 9 0 0 0-16 3 M4 17a9 9 0 0 0 16-3',logout:'M10 4H4v16h6 M9 12h12 M17 8l4 4-4 4',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',users:'M9 9a3 3 0 1 1 0-6 3 3 0 0 1 0 6 M3 21v-4a6 6 0 0 1 12 0v4 M17 4a3 3 0 0 1 0 6 M18 14a4 4 0 0 1 3 4v3',audit:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5 M8 18h5',budget:'M4 3h16v18H4z M7 6h10v4H7z M7 14h2 M15 14h2 M7 18h2 M15 18h2',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 M7 9l5-5 5 5 M4 17v4h16v-4',clock:'M12 7v5l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chevrons:'M8 9l4-4 4 4 M8 15l4 4 4-4',more:'M5 12h.01 M12 12h.01 M19 12h.01',edit:'M4 16l11-11 4 4L8 20H4z M13 7l4 4',cloud:'M7 19a5 5 0 1 1 0-10 7 7 0 0 1 13 1 5 5 0 0 1-1 9H7z','arrow-right':'M4 12h16 M14 6l6 6-6 6'};
function ico(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=ico(e.dataset.icon))}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,max=2)=>v===null||v===undefined?'—':Number(v).toLocaleString('ru-RU',{maximumFractionDigits:max});
function compact(v){if(v===null||v===undefined)return '—';let n=Number(v),a=Math.abs(n);return a>=1e9?fmt(n/1e9,2)+' млрд':a>=1e6?fmt(n/1e6,2)+' млн':fmt(n,2)}
function dte(v){return v?new Date(v+'T00:00:00').toLocaleDateString('ru-RU',{day:'2-digit',month:'short'}).replace(' г.',''):''}
const has=p=>S.user?.permissions.includes(p);
function toast(t,error=false){$('toast').textContent=t;$('toast').className='toast visible'+(error?' error':'');clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4400)}
async function api(url,opts={}){let headers={'Content-Type':'application/json','X-CSRF-Token':S.csrf,...opts.headers};const r=await fetch(url,{credentials:'same-origin',...opts,headers});let data;try{data=await r.json()}catch{throw Error('Сервер вернул некорректный ответ. Проверьте окно запуска.')}
 if(!r.ok){if(r.status===401&&url!='/api/login')showLogin();let message=Array.isArray(data.detail)?data.detail.map(d=>`${d.loc?.slice(1).join('.')}: ${d.msg}`).join('; '):data.detail;throw Error(message||'Не удалось выполнить запрос.')}return data}
const post=(url,body={})=>api(url,{method:'POST',body:JSON.stringify(body)});
function showLogin(){S.user=null;S.csrf='';$('appShell').hidden=true;$('loginScreen').hidden=false;if($('modal').open)$('modal').close()}
const NAV=[['home','home','Обзор','Финансовый обзор','Счета, движение денег и ближайшие решения.','view'],['calendar','calendar','Платёжный календарь','Платёжный календарь','Поступления и утверждённые платежи по дням.','view'],['requests','requests','Заявки на оплату','Заявки на оплату','От заявки до подтверждённой операции.',''],['accounts','wallet','Банк и касса','Банк и касса','Каждый счёт — отдельный остаток и своя валюта.','view'],['ledger','transfer','Операции','Фактические операции','Приходы, расходы и внутренние переводы.','view'],['budgets','budget','Бюджеты и лимиты','Бюджеты и лимиты','Факт + утверждённые заявки. Мягкий или жёсткий контроль.','view'],['report','chart','Отчёт Cash Flow','Отчёт Cash Flow','Денежные потоки из реальных операций сайта.','view'],['model','file','FinModel · Excel','Финансовая модель','Снимок Excel с сохранением значений и ссылок на ячейки.','view'],['audit','audit','Журнал действий','Журнал действий','Кто, когда и что изменил в системе.','audit'],['users','users','Пользователи','Пользователи и доступ','Индивидуальные учётные записи и роли.','users'],['profile','settings','Мой профиль','Мой профиль','Личная учётная запись и безопасность.','']];
function allowed(item){return !item[5]||item[5]==='audit'?(!item[5]||['admin','director','finance'].includes(S.user?.role)):has(item[5])}
function navHtml(item,active){return `<button data-page="${item[0]}" class="${active?'active':''}">${ico(item[1])}<span>${item[2]}</span></button>`}
function renderNav(){const list=NAV.filter(allowed);$('sideNav').innerHTML=list.filter(x=>x[0]!=='profile').map((x,i)=>(x[0]==='model'?'<div class="nav-separator"></div>':'')+navHtml(x,x[0]===S.page)).join('');let mobile=has('view')?[['home','home','Обзор'],['calendar','calendar','Календарь'],['requests','requests','Заявки'],['accounts','wallet','Счета'],['more','more','Ещё']]:[['requests','requests','Мои заявки'],['profile','settings','Профиль']];$('mobileNav').innerHTML=mobile.map(x=>navHtml(x,x[0]===S.page||(x[0]==='more'&&!['home','calendar','requests','accounts'].includes(S.page)))).join('');$('userName').textContent=S.user.name;$('userRole').textContent=S.user.role_label;$('userAvatar').textContent=S.user.name.slice(0,2).toUpperCase();$('modelTopButton').hidden=!has('view');$('currency').parentElement.hidden=!has('view')}
async function start(){try{const me=await api('/api/me');S.user=me.user;S.csrf=me.csrf;await enter()}catch(e){showLogin()}}
async function bootstrap(){const b=await api('/api/bootstrap');Object.assign(S,{accounts:b.accounts,categories:b.categories,user:b.user,csrf:b.csrf,today:b.today})}
async function enter(){await bootstrap();$('loginScreen').hidden=true;$('appShell').hidden=false;let page=location.hash.slice(1)||'home';if(!has('view'))page='requests';await navigate(page)}
async function navigate(page){const item=NAV.find(x=>x[0]===page);if(page!=='more'&&(!item||!allowed(item)))page=has('view')?'home':'requests';S.page=page;history.replaceState(null,'','#'+page);renderNav();const n=NAV.find(x=>x[0]===page)||['more','more','Разделы','Все разделы','Быстрый доступ к инструментам.'];$('pageTitle').textContent=n[3];$('pageSubtitle').textContent=n[4];$('breadTitle').textContent=n[2];$('pageEyebrow').textContent=page==='home'?'ВАШИ ФИНАНСЫ В ОДНОМ МЕСТЕ':'ZUMA · '+n[2].toUpperCase();await renderPage();window.scrollTo({top:0,behavior:'smooth'})}
function empty(title,text,action='',label='',icon='wallet',compactFlag=false){return `<div class="empty${compactFlag?' compact':''}"><div class="icon-box teal">${ico(icon)}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action?`<button class="btn primary" data-action="${action}">${ico('plus')}${esc(label)}</button>`:''}</div>`}
const badge=(text,color='gray')=>`<span class="badge ${color}">${esc(text)}</span>`;
const STATUS={draft:['Черновик','gray'],pending:['На согласовании','amber'],approved:['Утверждена','green'],rejected:['Отклонена','red'],paid:['Оплачена','blue'],expected:['Ожидается','amber'],received:['Получено','green']};
const st=s=>badge(...(STATUS[s]||[s,'gray']));
function metrics(items){return `<div class="metrics">${items.map(x=>`<article class="metric"><div class="metric-top">${esc(x[0])}<span class="${x[4]||''}">${ico(x[3]||'chart')}</span></div><div class="metric-value ${x[4]||''}">${esc(compact(x[1]))}</div><div class="metric-note">${esc(x[2])}</div></article>`).join('')}</div>`}
function horizon(){return `<div class="segmented">${[7,30,90].map(n=>`<button data-action="days" data-days="${n}" class="${S.days===n?'active':''}">${n} дней</button>`).join('')}</div>`}
function chart(data){if(data.balance===null)return empty('Нет исходного остатка','Добавьте счета и кассу для расчёта прогноза.','','','chart',true);const a=data.forecast.map(x=>Number(x.balance));if(!a.length)return '';const reserve=Number(data.reserve),W=740,H=220,L=53,R=18,T=20,B=35;let lo=Math.min(0,...a,reserve),hi=Math.max(0,...a,reserve);if(hi===lo)hi=lo+100;hi+=Math.abs(hi-lo)*.14;lo-=Math.abs(hi-lo)*.04;const y=v=>T+(H-T-B)*(hi-v)/(hi-lo),x=i=>L+(W-L-R)*i/(a.length-1||1);let out=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Прогноз остатка в выбранной валюте"><defs><linearGradient id="cfArea" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#168b78" stop-opacity=".15"/><stop offset="1" stop-color="#168b78" stop-opacity=".015"/></linearGradient></defs>`;
 for(let i=0;i<=3;i++){const v=lo+(hi-lo)*i/3;out+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#edf2f5" stroke-dasharray="3 4"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end" font-size="9" fill="#97a5b5">${esc(compact(v))}</text>`}
 const points=a.map((v,i)=>`${x(i)},${y(v)}`).join(' ');out+=`<polygon points="${x(0)},${H-B} ${points} ${x(a.length-1)},${H-B}" fill="url(#cfArea)"/><polyline points="${points}" fill="none" stroke="#168b78" stroke-width="2.5" stroke-linejoin="round"/><line x1="${L}" x2="${W-R}" y1="${y(reserve)}" y2="${y(reserve)}" stroke="#c79a55" stroke-width="1" stroke-dasharray="5 5"/>`;
 [0,Math.floor(a.length/4),Math.floor(a.length/2),Math.floor(a.length*.75),a.length-1].forEach(i=>out+=`<text x="${x(i)}" y="${H-10}" text-anchor="${i===0?'start':i===a.length-1?'end':'middle'}" font-size="9" fill="#97a5b5">${esc(dte(data.forecast[i].date))}</text>`);
 a.forEach((v,i)=>out+=`<circle cx="${x(i)}" cy="${y(v)}" r="${v<reserve?3:2.5}" fill="${v<reserve?'#d45462':'#168b78'}"><title>${esc(dte(data.forecast[i].date))}: ${fmt(v)} ${S.currency}</title></circle>`);return out+'</svg>'}
async function renderPage(){const token=++S.renderId;$('content').innerHTML='<div class="loader"><span class="spinner"></span><div>Загружаем данные с сервера…</div></div>';try{let html='';if(S.page==='home')html=await pageHome();else if(S.page==='calendar')html=await pageCalendar();else if(S.page==='requests')html=await pageRequests();else if(S.page==='accounts')html=await pageAccounts();else if(S.page==='ledger')html=await pageLedger();else if(S.page==='budgets')html=await pageBudgets();else if(S.page==='model')html=await pageModel();else if(S.page==='report')html=await pageReport();else if(S.page==='users')html=await pageUsers();else if(S.page==='audit')html=await pageAudit();else if(S.page==='profile')html=pageProfile();else html=pageMore();if(token===S.renderId)$('content').innerHTML=html}catch(e){if(token===S.renderId)$('content').innerHTML=`<div class="banner">${ico('warning')}<div><b>Не удалось загрузить данные</b><p>${esc(e.message)}</p><button class="btn link" data-action="refresh">Повторить</button></div></div>`}}
async function pageHome(){const [d,a,m,r]=await Promise.all([api(`/api/dashboard?currency=${S.currency}&days=${S.days}`),api('/api/accounts'),api('/api/model'),api('/api/requests')]);S.dashboard=d;S.fullAccounts=a;S.requests=r;let ac=a.filter(a=>a.currency===S.currency);const risk=d.forecast.find(x=>x.risk);let html=`<div class="hero-grid"><article class="balance-hero"><div class="hero-top"><span>Денежные средства сейчас</span>${badge(dte(d.as_of)+' · '+S.currency,'translucent')}</div><div class="hero-amount">${d.balance===null?'Счета не настроены':fmt(d.balance)}${d.balance!==null?`<small>${S.currency}</small>`:''}</div><div class="hero-sub">${d.balance===null?'Укажите подтверждённые начальные остатки банка и кассы.':`${ac.length} счетов · Начальные остатки + фактические операции`}</div><div class="hero-bottom"><span>Минимальный резерв: ${fmt(d.reserve)} ${S.currency}</span><button class="btn dark-light" data-page="accounts">Банк и касса ${ico('arrow-right')}</button></div></article><article class="review-card"><div class="review-top"><div class="icon-box amber">${ico('requests')}</div><div><h3>Требуют решения</h3><p>Заявки в выбранной валюте</p></div></div><div class="review-amount">${d.pending_count}<small> ${d.pending_count===1?'заявка':'заявок'}</small></div><div class="review-foot"><span class="small muted">На сумму <b>${compact(d.pending_amount)} ${S.currency}</b></span><button class="btn soft tiny" data-page="requests">Посмотреть ${ico('arrow-right')}</button></div></article></div>`;
 html+=metrics([['Поступления · 7 дней',d.incoming7,'Ожидаемые · '+S.currency,'in','in'],['Платежи · 7 дней',d.outgoing7,'Только утверждённые · '+S.currency,'out','out'],['Фактический приход · месяц',d.fact_in,'Операции сайта · '+S.currency,'wallet'],['Фактический расход · месяц',d.fact_out,'Без внутренних переводов · '+S.currency,'transfer']]);
 if(!d.account_count)html+=`<div class="banner blue">${ico('info')}<div><b>Начните с подтверждённых остатков</b><p>В FinModel есть исторические суммы. Они не выданы за остатки на сегодня. Добавьте банковский счёт или кассу с датой начала учёта.</p></div></div>`;
 html+=`<div class="grid-main"><div class="panel"><div class="panel-head"><div><h3>Прогноз денежных средств</h3><p>${S.currency} · Утверждённые платежи и ожидаемые поступления</p></div>${horizon()}</div><div class="chart-box">${chart(d)}</div><div class="chart-legend"><span><i class="legend-line"></i>Прогнозный остаток</span><span><i class="legend-line dash"></i>Минимальный резерв</span></div><div class="panel-note">${esc(!d.forecast_has_events?'Будущие события пока не зарегистрированы. Это не подтверждение отсутствия кассового разрыва.':d.note)}</div></div><div class="panel"><div class="panel-head"><h3>Финансовый контроль</h3>${ico('lock')}</div><div class="panel-body"><div class="insight ${risk?'warning':'good'}">${ico(risk?'warning':'check')}<div><b>${risk?'Остаток ниже резерва · '+dte(risk.date):d.account_count?'Контроль по введённым данным':'Нужны исходные данные'}</b><p>${risk?`${fmt(risk.balance)} ${S.currency}. Проверьте график поступлений и выплат.`:'Прогноз не учитывает обязательства, которые ещё не внесены в систему.'}</p></div></div><div class="insight ${d.overdue_count?'warning':''}">${ico('clock')}<div><b>Просроченные события: ${d.overdue_count}</b><p>В прогнозе просрочка условно включена в сегодняшний день. Уточните даты.</p></div></div><div class="insight">${ico('file')}<div><b>${m.snapshot?'FinModel подключена как снимок':'FinModel ещё не загружена'}</b><p>${m.snapshot?`${m.snapshot.sheet_names.length} листов в файле. Исторические показатели отделены от операций сайта.`:'Добавьте XLSX в разделе финансовой модели.'}</p><button class="btn link small" data-page="model">Открыть модель →</button></div></div></div></div></div>`;
 html+=`<div class="grid-main"><div class="panel"><div class="panel-head"><div><h3>Ближайшие платежи</h3><p>Неоплаченные утверждённые заявки · ${S.currency}</p></div><button class="btn link small" data-page="calendar">Календарь →</button></div>${paymentTable(r.filter(x=>x.status==='approved'&&x.currency===S.currency).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5))}</div><div class="panel"><div class="panel-head"><h3>Где находятся деньги</h3>${badge(S.currency,'gray')}</div><div class="panel-body">${ac.length?ac.map(a=>`<div class="account-mini"><div class="icon-box ${a.kind==='bank'?'blue':'teal'}">${ico(a.kind==='bank'?'bank':'cash')}</div><div><b>${esc(a.name)}</b><small>${a.kind==='bank'?'Банковский счёт':'Касса'}</small></div><div class="num">${compact(a.balance)}<small>${a.currency}</small></div></div>`).join(''):empty('Банк и касса','Добавьте первый счёт для начала учёта.',has('write')?'new-account':'','Добавить счёт','wallet',true)}</div></div></div>`;return html}
function paymentTable(rows){return rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Контрагент</th><th>Дата</th><th class="num">Сумма</th><th>Статус</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="main-cell">${esc(r.counterparty)}<span class="subline">${esc(r.category)}</span></td><td>${dte(r.date)}</td><td class="num bold">${fmt(r.amount)}<span class="subline">${r.currency}</span></td><td>${r.overdue?badge('Просрочено','red'):st(r.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('Нет утверждённых платежей','После согласования заявки появятся здесь.','','','calendar',true)}
async function pageCalendar(){const [d,r]=await Promise.all([api(`/api/dashboard?currency=${S.currency}&days=${S.days}`),api('/api/receipts')]);S.receipts=r;S.dashboard=d;return `<div class="toolbar"><div class="toolbar-left">${horizon()}<span class="small muted">${S.currency}</span></div><div class="toolbar-right">${has('schedule')?`<button class="btn secondary" data-action="new-receipt">${ico('plus')} План поступления</button>`:''}</div></div>${!d.account_count?`<div class="banner">${ico('warning')}<div><b>Нет исходных остатков в ${S.currency}</b><p>Добавьте счёт. Нулевые значения календаря пока не являются прогнозом ликвидности.</p></div></div>`:''}<div class="panel"><div class="panel-head"><div><h3>Движение средств по дням</h3><p>Только зарегистрированные события; заявки на согласовании не включены</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Дата</th><th>События</th><th class="num">Поступления</th><th class="num">Платежи</th><th class="num">Прогноз остатка</th></tr></thead><tbody>${d.forecast.map(day=>`<tr><td>${dte(day.date)}</td><td>${day.events.length?day.events.map(e=>`${e.kind==='in'?'↙':'↗'} ${esc(e.name)}${e.overdue?' · просрочка':''}`).join('<br>'):'<span class="muted">Не зарегистрированы</span>'}</td><td class="num in">${Number(day.incoming)?'+'+fmt(day.incoming):'—'}</td><td class="num out">${Number(day.outgoing)?'−'+fmt(day.outgoing):'—'}</td><td class="num bold ${day.risk?'out':''}">${d.account_count?fmt(day.balance):'—'}</td></tr>`).join('')}</tbody></table></div><div class="panel-note">${esc(d.note)}</div></div><div class="panel"><div class="panel-head"><div><h3>Ожидаемые поступления</h3><p>Получение денег подтверждается отдельной фактической операцией</p></div></div>${r.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Контрагент</th><th>Дата</th><th>Счёт</th><th class="num">Сумма</th><th>Статус</th><th></th></tr></thead><tbody>${r.filter(r=>r.currency===S.currency).map(r=>`<tr><td>${esc(r.counterparty)}</td><td>${dte(r.date)}</td><td>${esc(r.account)}</td><td class="num">${fmt(r.amount)} ${r.currency}</td><td>${st(r.status)}</td><td>${r.status==='expected'&&has('write')?`<button class="btn tiny soft" data-action="receive" data-id="${r.id}">Подтвердить приход</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Ожидаемые поступления не внесены','Укажите контрагента, счёт, сумму и ожидаемую дату.','','','in',true)}</div>`}
async function pageRequests(){S.requests=await api('/api/requests');const count=S.requests.filter(x=>x.status==='pending').length;return `<div class="toolbar"><div class="toolbar-left"><div class="tabs">${[['all','Все'],['pending','На согласовании · '+count],['approved','Утверждённые'],['paid','Оплаченные'],['draft','Черновики']].map(x=>`<button data-action="filter" data-filter="${x[0]}" class="${S.filter===x[0]?'active':''}">${x[1]}</button>`).join('')}</div></div><input id="requestSearch" class="search-input" placeholder="Поиск контрагента или заявки" value="${esc(S.search)}"></div><div id="requestList">${requestCards()}</div><div class="small muted" style="margin-top:17px">Показаны последние 500 заявок. Частичные оплаты пока не поддерживаются; факт фиксируется на полную сумму.</div>`}
function requestCards(){let rows=S.requests.filter(r=>(S.filter==='all'||r.status===S.filter)&&`${r.number} ${r.counterparty} ${r.category}`.toLowerCase().includes(S.search.toLowerCase()));if(!rows.length)return `<div class="panel">${empty('Заявок пока нет','Создайте заявку: укажите статью, контрагента, сумму и дату.','new-request','Создать заявку','requests')}</div>`;return `<div class="request-cards">${rows.map(r=>`<article class="request-card"><div class="request-card-top"><span>${r.number} ${r.overdue?'· '+badge('Просрочено','red'):''}</span>${st(r.status)}</div><h3>${esc(r.counterparty)}</h3><p>${esc(r.category)}</p><div class="request-card-value">${fmt(r.amount)}<small>${r.currency}</small></div><div class="meta-row"><span>${ico('calendar')}${dte(r.date)}</span><span>${ico('wallet')}${esc(r.account)}</span></div><div class="request-card-foot"><span>${r.budget.hidden?badge('Проверяет финансист'):r.budget.limit===null?badge('Лимит не задан'):r.budget.over?badge('Сверх лимита','amber'):badge('В пределах лимита','green')}</span><div class="cell-actions"><button class="btn tiny secondary" data-action="request-detail" data-id="${r.id}">Открыть</button>${r.status==='pending'&&has('approve')?`<button class="btn tiny soft" data-action="approve" data-id="${r.id}">${ico('check')} Согласовать</button>`:''}${r.status==='approved'&&has('write')?`<button class="btn tiny primary" data-action="pay" data-id="${r.id}">Факт оплаты</button>`:''}${r.status==='draft'&&(r.creator_id===S.user.id||S.user.role==='admin')?`<button class="btn tiny soft" data-action="submit-request" data-id="${r.id}">Отправить</button>`:''}</div></div></article>`).join('')}</div>`}
async function pageAccounts(){S.fullAccounts=await api('/api/accounts');return `<div class="toolbar"><div class="small muted">Начальный остаток задаётся на начало выбранного дня. Суммы разных валют не складываются.</div>${has('write')?`<button class="btn primary" data-action="new-account">${ico('plus')} Добавить счёт / кассу</button>`:''}</div>${S.fullAccounts.length?`<div class="account-grid">${S.fullAccounts.map(a=>`<article class="account-card"><div class="account-card-head"><div class="icon-box ${a.kind==='bank'?'blue':'teal'}">${ico(a.kind==='bank'?'bank':'cash')}</div>${badge(a.currency,'gray')}</div><h3>${esc(a.name)}</h3><p>${a.kind==='bank'?'Банковский счёт':'Наличные деньги · касса'}</p><div class="account-card-value">${fmt(a.balance)} <span class="small muted">${a.currency}</span></div><div class="account-card-foot"><span>Учёт с ${a.opening_date}</span><b>${a.allow_overdraft?'Овердрафт разрешён':'Без отрицательного остатка'}</b></div></article>`).join('')}</div>`:`<div class="panel">${empty('Добавьте первый счёт','Укажите реальный остаток банка или кассы. Исторические суммы из Excel не подставляются автоматически.',has('write')?'new-account':'','Добавить счёт','bank')}</div>`}<div class="banner blue" style="margin-top:20px">${ico('info')}<div><b>Банк и касса — отдельно</b><p>Перевод между своими счетами одной валюты меняет их остатки, но не увеличивает приход и расход компании. Валютная конвертация в эту версию не включена.</p></div></div>`}
async function pageLedger(){S.ledger=await api('/api/ledger');return `<div class="toolbar"><div class="toolbar-left">${has('write')?`<button class="btn primary" data-action="new-ledger">${ico('plus')} Добавить операцию</button>`:''}<span class="small muted">Последние 500 операций</span></div><a class="btn secondary" href="/api/export/ledger.csv">${ico('download')} Экспорт CSV</a></div><div class="panel">${S.ledger.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Дата / документ</th><th>Операция</th><th>Контрагент / статья</th><th>Счёт</th><th class="num">Сумма</th><th></th></tr></thead><tbody>${S.ledger.map(t=>`<tr><td>${dte(t.date)}<span class="subline">${esc(t.reference)}</span></td><td>${badge(t.kind==='in'?'Поступление':t.kind==='out'?'Расход':'Перевод',t.kind==='in'?'green':t.kind==='out'?'red':'blue')}${t.reversed?'<span class="subline">Сторнирована</span>':t.reversal_of?'<span class="subline">Сторно #'+t.reversal_of+'</span>':''}</td><td>${esc(t.counterparty||'Между своими счетами')}<span class="subline">${esc(t.category)}</span></td><td>${esc(t.account)}${t.to_account?'<span class="subline">→ '+esc(t.to_account)+'</span>':''}</td><td class="num bold ${t.kind==='in'?'in':t.kind==='out'?'out':''}">${t.kind==='in'?'+':t.kind==='out'?'−':''}${fmt(t.amount)}<span class="subline">${t.currency}</span></td><td>${!t.reversed&&!t.reversal_of&&['admin','finance'].includes(S.user.role)?`<button class="btn tiny secondary" data-action="reverse" data-id="${t.id}">Сторно</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Реестр операций пуст','Внесите приход, расход или внутренний перевод. Каждая операция сохраняется в базе данных.',has('write')?'new-ledger':'','Добавить операцию','transfer')}</div><div class="banner blue">${ico('lock')}<div><b>Записи не удаляются</b><p>Ошибка исправляется через «Сторно» с обязательной причиной. Исходная операция и журнал действий сохраняются. Для банковских данных пока предусмотрен ручной ввод, не автоматическая загрузка выписки.</p></div></div>`}
async function pageBudgets(){S.budgetMonth=S.budgetMonth||S.today.slice(0,7);S.budgets=await api(`/api/budgets?month=${S.budgetMonth}&currency=${S.currency}`);return `<div class="toolbar"><div class="toolbar-left"><input id="budgetMonth" type="month" value="${S.budgetMonth}"><span class="small muted">${S.currency} · Факт + резерв по заявкам</span></div><div class="toolbar-right">${has('budget')?`<button class="btn secondary" data-action="new-category">${ico('plus')} Статья</button><button class="btn secondary" data-action="reserve">${ico('lock')} Резерв ликвидности</button>`:''}</div></div><div class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Статья</th><th class="num">Лимит</th><th class="num">Оплачено</th><th class="num">Утверждено, не оплачено</th><th class="num">Осталось</th><th>Контроль</th><th></th></tr></thead><tbody>${S.budgets.map(b=>`<tr><td class="main-cell">${esc(b.category)}${b.source?'<span class="subline">'+esc(b.source)+'</span>':''}</td><td class="num bold">${fmt(b.limit)}</td><td class="num">${fmt(b.spent)}</td><td class="num">${fmt(b.reserved)}</td><td class="num ${Number(b.remaining)<0?'out':'in'}">${fmt(b.remaining)}</td><td>${b.limit===null?badge('Не настроен'):badge(b.mode==='hard'?'Жёсткий':'Мягкий',b.mode==='hard'?'red':'green')}</td><td>${has('budget')?`<button class="btn tiny secondary" data-action="budget" data-id="${b.category_id}">${ico('edit')} ${b.limit===null?'Задать':'Изменить'}</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="panel-note">При мягком превышении обязательно обоснование. При жёстком — блокировка на сервере. Смена лимита или режима сохраняется в журнале с причиной.</div></div><div class="banner blue">${ico('file')}<div><b>Сначала подтвердите соответствие статей</b><p>Месячный план FinModel хранится отдельно. Перенос суммы в платёжный бюджет выполняется вручную с указанием исходной ячейки, чтобы не выдать начисленные расходы за календарь оплат.</p></div></div>`}
async function pageModel(){S.model=await api('/api/model'+(S.modelVersion?'?version='+S.modelVersion:''));const m=S.model,sp=m.snapshot;if(!sp)return `<div class="panel">${empty('Загрузите финансовую модель','Поддерживается FinModel Zuma со структурой исходного файла.',has('import')?'upload-model':'','Загрузить XLSX','file')}</div>`;let current=sp.sheets.find(s=>s.key===S.modelKey)||sp.sheets[0];S.modelKey=current.key;
 return `<div class="model-summary"><div class="model-source"><div class="icon-box teal">${ico('file')}</div><div><h3>${esc(sp.filename)}</h3><p>${sp.sheet_names.length} листов · ${sp.sheets.length} отчётных блоков · Снимок сохранённых значений</p><p>Версия ${m.selected} · Исходный Excel не изменён</p></div></div><div class="model-source"><div class="icon-box amber">${ico('warning')}</div><div><h3>Нужна проверка исходной модели</h3><p>${sp.error_count} ошибок Excel · ${sp.missing_cache_count} формул без сохранённого результата</p><p>Ошибки и противоречивые даты не исправлены автоматически</p></div></div></div><div class="toolbar"><div class="toolbar-left"><select id="modelVersion" class="version-select">${m.versions.map(v=>`<option value="${v.id}" ${v.id===m.selected?'selected':''}>Версия ${v.id} · ${esc(v.imported_at.slice(0,16))}</option>`).join('')}</select><button class="btn secondary" data-action="model-errors">${ico('info')} Диагностика</button></div><div class="toolbar-right">${has('import')?`<button class="btn secondary" data-action="drive-sync">${ico('cloud')} ${m.drive_configured?'Обновить из Drive':'Подключить Drive'}</button><button class="btn primary" data-action="upload-model">${ico('upload')} Загрузить XLSX</button>`:''}</div></div><details class="model-warning" open><summary>Как интерпретировать данные · ${sp.warnings.length} замечаний</summary><ul class="warning-list">${sp.warnings.map(w=>`<li>${ico('info')}<span>${esc(w)}</span></li>`).join('')}</ul></details><div class="toolbar"><div class="model-view-tabs tabs">${sp.sheets.map(sh=>`<button class="${sh.key===S.modelKey?'active':''}" data-action="model-tab" data-key="${sh.key}">${esc({pnl:'План / факт',cfplan:'CF финмодели',cash:'Исходный Cash Flow',balance:'Баланс',opex:'OPEX',debt:'Кредитный график'}[sh.key])}</button>`).join('')}</div>${current.paired?`<div class="segmented">${[['both','План + факт'],['plan','План'],['fact','Факт']].map(x=>`<button data-action="model-mode" data-mode="${x[0]}" class="${S.modelMode===x[0]?'active':''}">${x[1]}</button>`).join('')}</div>`:''}</div><div class="panel"><div class="panel-head"><div><h3>${esc(current.title)}</h3><p>${esc(current.sheet)} · Исходные единицы измерения, без масштабирования</p></div>${badge('Источник Excel','blue')}</div>${modelTable(current)}<div class="panel-note">Наведите курсор на число: показаны адрес ячейки и исходная формула. Пустые ячейки — «—», нули сохранены. Этот снимок не изменяет оперативные остатки, заявки и лимиты.</div></div>`}
function modelTable(sh){let cols=sh.periods.map((p,i)=>i).filter(i=>!sh.paired||S.modelMode==='both'||(S.modelMode==='plan'?i%2===0:i%2===1));function head(i){let p=sh.periods[i],dt=p.date||(sh.paired&&i%2===1?sh.periods[i-1]?.date:null);return dt?new Date(dt+'T00:00:00').toLocaleDateString('ru-RU',{month:'short',year:'numeric'}):p.column}
 return `<div class="table-scroll"><table class="data-table model-table"><thead><tr><th>Показатель / источник</th>${cols.map(i=>`<th class="num ${sh.paired?(i%2===0?'plan-head':'fact-head'):''}">${esc(head(i))}${sh.paired?`<br>${i%2===0?'План':'Факт'}`:''}</th>`).join('')}</tr></thead><tbody>${sh.rows.map(r=>`<tr><td class="label-cell">${esc(r.label).replace(/\n/g,'<br>')}<small>${esc(sh.sheet)} · строка ${r.row}</small></td>${cols.map(i=>{const c=r.cells[i],v=c.value,title=c.source+(c.formula?'\n='+c.formula:'');let numeric=v!==null&&v!==''&&c.type!=='e'&&Number.isFinite(Number(v));return `<td class="num ${c.type==='e'?'error':numeric&&Number(v)===0?'zero':numeric&&Number(v)<0?'neg':''}" title="${esc(title)}">${numeric?fmt(v,4):esc(v??'—')}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
async function pageReport(){S.reportYear=S.reportYear||Number(S.today.slice(0,4));const r=await api(`/api/report?year=${S.reportYear}&currency=${S.currency}`);const sums=r.totals;return `<div class="toolbar"><div class="toolbar-left"><select id="reportYear">${[2025,2026,2027,2028].map(y=>`<option ${S.reportYear===y?'selected':''}>${y}</option>`).join('')}</select><span class="small muted">${S.currency} · ${r.year}</span></div><button class="btn secondary" data-action="print">${ico('file')} Печать</button></div><div class="panel"><div class="panel-head"><h3>Движение денег по статьям</h3>${badge('Факт сайта','green')}</div>${r.rows.length?`<div class="table-scroll"><table class="data-table model-table"><thead><tr><th>Статья</th>${['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'].map(m=>`<th class="num">${m}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr><td>${esc(row.category)}<span class="subline">${esc({operating:'Операционная',investing:'Инвестиционная',financing:'Финансовая'}[row.activity])}</span></td>${row.values.map(v=>`<td class="num ${Number(v)<0?'out':'in'}">${fmt(v)}</td>`).join('')}</tr>`).join('')}<tr><td><b>Чистый денежный поток</b></td>${sums.map(v=>`<td class="num bold">${fmt(v)}</td>`).join('')}</tr></tbody></table></div>`:empty('Нет фактических операций за период','Этот отчёт строится из базы сайта, не из исторического снимка FinModel.','','','chart')}<div class="panel-note">${esc(r.note)}</div></div>`}
async function pageUsers(){S.users=await api('/api/users');return `<div class="toolbar"><span class="small muted">Администратор управляет пользователями. Роль проверяется сервером.</span><button class="btn primary" data-action="new-user">${ico('plus')} Добавить пользователя</button></div><div class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Имя</th><th>Логин</th><th>Роль</th><th>Статус</th><th></th></tr></thead><tbody>${S.users.map(u=>`<tr><td class="main-cell">${esc(u.name)}</td><td>${esc(u.username)}</td><td>${esc(u.role_label)}</td><td>${badge(u.active?'Активен':'Отключён',u.active?'green':'red')}</td><td><button class="btn tiny secondary" data-action="edit-user" data-id="${u.id}">${ico('edit')} Управлять</button></td></tr>`).join('')}</tbody></table></div></div><div class="banner blue">${ico('lock')}<div><b>Разделение полномочий</b><p>Сотрудник видит только свои заявки. Директор согласовывает чужие заявки. Бухгалтер фиксирует факт. Финансист управляет лимитами и импортом. Администратор имеет полный доступ; в пилоте может согласовать свою заявку, и это фиксируется в журнале.</p></div></div>`}
async function pageAudit(){let rows=await api('/api/audit');return `<div class="panel"><div class="panel-head"><h3>Последние 200 событий</h3>${badge('Без удаления через интерфейс','blue')}</div><div class="table-scroll"><table class="data-table"><thead><tr><th>Дата (UTC)</th><th>Пользователь</th><th>Действие</th><th>Объект</th><th>Подробности</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.date.slice(0,19))}</td><td>${esc(r.user)}</td><td>${esc(r.action)}</td><td>${esc(r.entity)} #${esc(r.entity_id)}</td><td style="white-space:normal;min-width:250px;max-width:480px">${esc(r.detail)}</td></tr>`).join('')}</tbody></table></div><div class="panel-note">Журнал в базе защищён правами приложения, но не является криптографически неизменяемым архивом. Администратор сервера имеет доступ к базе.</div></div>`}
function pageProfile(){return `<div class="profile-grid"><div class="panel"><div class="profile-info"><span class="avatar">${esc(S.user.name.slice(0,2).toUpperCase())}</span><div><h3>${esc(S.user.name)}</h3><small>${esc(S.user.username)} · ${esc(S.user.role_label)}</small></div></div><div class="panel-body"><button class="btn secondary" data-action="password">${ico('lock')} Изменить пароль</button><button class="btn link" data-action="logout" style="margin-left:15px">Выйти</button></div></div><div class="panel"><div class="panel-head"><h3>О системе</h3></div><div class="panel-body"><p class="small muted">ZUMA Cash Flow v1.0 · Пилот<br>Интерфейс → Python API → серверная база данных.<br>Финансовые данные не хранятся в LocalStorage браузера.<br>Сессия действует 8 часов; после смены пароля все входы отзываются.</p></div></div></div>`}
function pageMore(){return `<div class="more-grid">${NAV.filter(allowed).map(n=>`<button class="more-card" data-page="${n[0]}"><span class="icon-box teal">${ico(n[1])}</span>${n[2]}</button>`).join('')}</div>`}
/* Формы */
const option=(value,label,selected)=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;
function inp(name,label,type='text',value='',extra=''){return `<label>${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`}
function sel(name,label,options,value,extra=''){return `<label>${label}<select name="${name}" ${extra}>${options.map(o=>option(o[0],o[1],value)).join('')}</select></label>`}
function area(name,label,value='',extra=''){return `<label class="span-2">${label}<textarea name="${name}" rows="3" ${extra}>${esc(value)}</textarea></label>`}
const accountOptions=()=>S.accounts.map(a=>[a.id,`${a.name} · ${a.currency}`]);const categoryOptions=()=>S.categories.map(c=>[c.id,c.name]);const roleOptions=()=>[['admin','Администратор'],['director','Директор'],['finance','Финансист'],['accountant','Бухгалтер'],['employee','Сотрудник']];
function modal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;hydrateIcons();if(!$('modal').open)$('modal').showModal()}
function form(title,fields,onSubmit,options={}){modal(title,`${options.note?'<div class="form-note">'+esc(options.note)+'</div>':''}<form id="actionForm"><div class="form-grid">${fields}</div><div class="form-error" id="actionError" role="alert"></div><div class="form-actions"><button class="btn secondary" type="button" data-action="close-modal">Отмена</button><button class="btn primary" type="submit">${esc(options.button||'Сохранить')}</button></div></form>`);$('actionForm').onsubmit=async e=>{e.preventDefault();let button=e.submitter;button.disabled=true;$('actionError').textContent='';try{await onSubmit(Object.fromEntries(new FormData(e.target)),e.target);$('modal').close();if(!S.user){toast('Войдите с новым паролем');return}await bootstrap();await renderPage();toast(options.success||'Данные сохранены в базе')}catch(error){$('actionError').textContent=error.message}finally{button.disabled=false}}}
async function ensureAccounts(){await bootstrap();if(S.accounts.length)return true;modal('Сначала добавьте счёт',empty('Нет банка или кассы','Заявке нужен счёт списания. Финансист или бухгалтер должен сначала задать реальные начальные остатки.',has('write')?'new-account':'','Добавить счёт','bank',true));return false}
function newAccount(){form('Новый счёт или касса',inp('name','Название','text','','required maxlength="160" placeholder="Например, основной расчётный счёт"')+sel('kind','Тип',[['bank','Банковский счёт'],['cash','Касса']],'bank')+sel('currency','Валюта',[['UZS','UZS · сум'],['USD','USD · доллар'],['EUR','EUR · евро']],S.currency)+inp('opening','Подтверждённый остаток','number','0','required min="0" step="0.01"')+inp('opening_date','Дата начала учёта','date',S.today,'required')+'<label class="check-label"><input type="checkbox" name="allow_overdraft">Разрешить овердрафт (только банк)</label>',d=>post('/api/accounts',{...d,allow_overdraft:d.allow_overdraft==='on'}),{note:'Остаток — на начало выбранного дня. Не вводите исторический остаток Excel как деньги на сегодня. После создания сумма не редактируется; исправления выполняются отдельными операциями.'})}
async function newRequest(){if(!await ensureAccounts())return;form('Новая заявка на расход',sel('account_id','Счёт списания',accountOptions())+sel('category_id','Статья расходов',categoryOptions(),S.categories.find(c=>c.name==='Закупка сырья')?.id)+inp('counterparty','Контрагент','text','','required minlength="2" maxlength="160"')+inp('amount','Сумма в валюте счёта','number','','required min="0.01" step="0.01" placeholder="0.00"')+inp('date','Плановая дата платежа','date',S.today,'required')+sel('status','Действие',[['pending','На согласование'],['draft','Сохранить черновик']],'pending')+inp('project','Проект / подразделение','text','','maxlength="120"')+area('purpose','Основание и обоснование расхода','','required minlength="5" maxlength="3000" placeholder="Договор, цель платежа; причина превышения лимита при необходимости"'),d=>post('/api/requests',{...d,account_id:Number(d.account_id),category_id:Number(d.category_id)}),{button:'Сохранить заявку',note:'Заявка — ещё не фактический расход. В календарь она попадёт после согласования. При жёстком превышении сервер заблокирует отправку; черновик сохранить можно.'})}
async function newReceipt(){if(!await ensureAccounts())return;form('Планируемое поступление',sel('account_id','Счёт получения',accountOptions())+sel('category_id','Статья поступления',categoryOptions(),S.categories.find(c=>c.name==='Поступления от покупателей')?.id)+inp('counterparty','Контрагент','text','','required minlength="2" maxlength="160"')+inp('amount','Сумма в валюте счёта','number','','required min="0.01" step="0.01"')+inp('date','Ожидаемая дата','date',S.today,'required')+area('note','Основание','','maxlength="2000"'),d=>post('/api/receipts',{...d,account_id:Number(d.account_id),category_id:Number(d.category_id)}),{note:'Это прогноз, не факт. После получения денег нажмите «Подтвердить приход» в календаре — ожидание будет закрыто без двойного учёта.'})}
async function newLedger(linked=null,isReceipt=false){if(!await ensureAccounts())return;let locked=!!linked;let kind=linked?(isReceipt?'in':'out'):'in';let aid=linked?.account_id||S.accounts[0].id;let cid=linked?.category_id||S.categories[0].id;
 let f=sel('kind','Тип операции',[['in','Поступление'],['out','Расход'],['transfer','Перевод между своими счетами']],kind,locked?'disabled':'')+sel('account_id','Счёт / касса',accountOptions(),aid,locked?'disabled':'')+`<div id="categoryWrap">${sel('category_id','Статья',categoryOptions(),cid,locked?'disabled':'')}</div><div id="targetWrap" hidden>${sel('to_account_id','Счёт-получатель',accountOptions(),S.accounts.find(a=>a.id!==aid)?.id)}</div>`+inp('amount','Сумма в валюте счёта','number',linked?.amount||'','required min="0.01" step="0.01"'+(locked?' readonly':''))+inp('date','Фактическая дата','date',S.today,'required')+inp('reference','Номер документа / выписки','text','','required minlength="2" maxlength="160" placeholder="Уникальный номер на этом счёте"')+inp('counterparty','Контрагент','text',linked?.counterparty||'','maxlength="160"')+area('note','Основание операции',linked?.purpose||linked?.note||'','maxlength="3000"');
 form(isReceipt?'Подтверждение поступления':linked?'Подтверждение факта оплаты':'Новая фактическая операция',f,d=>post('/api/ledger',{...d,kind:locked?kind:d.kind,account_id:locked?aid:Number(d.account_id),category_id:(locked?kind:d.kind)==='transfer'?null:locked?cid:Number(d.category_id),to_account_id:(locked?kind:d.kind)==='transfer'?Number(d.to_account_id):null,request_id:linked&&!isReceipt?linked.id:null,receipt_id:linked&&isReceipt?linked.id:null}),{note:'Сайт не отправляет платёж в банк. Здесь вы подтверждаете уже совершённую операцию по выписке или кассовому документу. Повторный документ на том же счёте не будет записан.'});let type=$('actionForm').elements.kind;type.addEventListener('change',()=>{let tr=type.value==='transfer';$('categoryWrap').hidden=tr;$('targetWrap').hidden=!tr})}
function approveRequest(r){form('Согласование · '+r.number,`<div class="span-2 detail-text"><b>${esc(r.counterparty)}</b><br>${fmt(r.amount)} ${r.currency} · ${dte(r.date)}<br>${esc(r.purpose)}</div>`+sel('action','Решение',[['approve','Утвердить'],['reject','Отклонить']],'approve')+area('note','Комментарий / обоснование','','maxlength="2000" placeholder="Обязательно при превышении мягкого лимита или отклонении"'),d=>post(`/api/requests/${r.id}/decision`,d),{button:'Подтвердить решение',note:r.budget.over?'Заявка превышает лимит. Для мягкого контроля требуется отдельное обоснование руководителя (не менее 10 символов).':'При согласовании сервер ещё раз проверит доступный лимит. Своя заявка согласуется другим руководителем, кроме администратора пилота.'})}
function requestDetail(r){modal(r.number+' · '+r.counterparty,`<div>${st(r.status)} ${r.overdue?badge('Просрочена','red'):''}</div><div class="detail-grid"><div><small>Сумма</small><b>${fmt(r.amount)} ${r.currency}</b></div><div><small>Плановая дата</small><b>${r.date}</b></div><div><small>Статья</small><b>${esc(r.category)}</b></div><div><small>Счёт</small><b>${esc(r.account)}</b></div></div><div class="detail-text">${esc(r.purpose)}</div>${r.decision_note?`<p class="small muted" style="margin-top:14px">Решение: ${esc(r.decision_note)}</p>`:''}<div class="form-actions">${r.status==='pending'&&has('approve')?`<button class="btn primary" data-action="approve" data-id="${r.id}">Согласовать / отклонить</button>`:''}${['approved','pending'].includes(r.status)&&['admin','director','finance'].includes(S.user.role)?`<button class="btn secondary" data-action="reschedule" data-id="${r.id}">Перенести</button>`:''}${r.status==='approved'&&has('write')?`<button class="btn primary" data-action="pay" data-id="${r.id}">Факт оплаты</button>`:''}</div>`)}
function budgetForm(id){let b=S.budgets.find(x=>x.category_id===id);form('Лимит · '+b.category,inp('amount','Лимит на '+S.budgetMonth+' · '+S.currency,'number',b.limit||'','required min="0" step="0.01"')+sel('mode','Режим контроля',[['soft','Мягкий · предупреждение'],['hard','Жёсткий · блокировка']],b.mode)+inp('source','Источник / ячейка FinModel','text',b.source||'Введён вручную','maxlength="240"')+area('reason','Причина установки или изменения','','required minlength="10" maxlength="1000"'),d=>post('/api/budgets',{...d,category_id:id,month:S.budgetMonth,currency:S.currency}),{note:'Расходы модели не считаются готовым платёжным лимитом. Подтвердите сумму и соответствие статьи вручную. Бюджет не добавляется в календарь как отдельный платёж.'})}
function userForm(user=null){if(user){form('Доступ · '+user.name,sel('role','Роль',roleOptions(),user.role)+sel('active','Доступ',[['true','Активен'],['false','Отключён']],String(user.active))+inp('password','Новый пароль (оставьте пустым, чтобы не менять)','password','','autocomplete="new-password" maxlength="128"'),d=>post('/api/users/'+user.id,{...d,active:d.active==='true'}),{note:'Изменение роли, пароля или статуса отзовёт все сессии этого пользователя.'})}else{form('Новый пользователь',inp('name','Имя','text','','required minlength="2" maxlength="160"')+inp('username','Логин (латиница)','text','','required pattern="[a-zA-Z0-9_.-]{3,80}" autocomplete="off"')+sel('role','Роль',roleOptions(),'employee')+inp('password','Начальный пароль · минимум 12 символов','password','','required minlength="12" maxlength="128" autocomplete="new-password"'),d=>post('/api/users',d),{note:'Передайте пароль сотруднику защищённым способом. После первого входа сотрудник может изменить его в профиле.'})}}
function uploadModel(){form('Загрузить новую версию FinModel','<label class="span-2">Excel-файл<input type="file" name="file" accept=".xlsx" required></label>',async(d,f)=>{let file=f.elements.file.files[0];if(file.size>20*1024*1024)throw Error('Файл больше 20 МБ.');let result=await api('/api/model/upload',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Filename':encodeURIComponent(file.name)},body:file});S.modelVersion=result.id},{button:'Импортировать снимок',note:'Новая версия сохраняется отдельно. Повторный файл определяется по SHA-256 и не дублируется. Исходные формулы не пересчитываются, операции и заявки не заменяются.'})}
function driveInfo(){modal('Google Drive · подключение',`<div class="form-note">Доступ ChatGPT к вашему Диску не передаётся сайту. Не публикуйте финансовый файл и не отправляйте ключи в чат.</div><p class="small muted">Для сайта нужен отдельный сервисный аккаунт с правом чтения только нужного файла. Создайте его в своём Google Cloud проекте, включите Drive API и поделитесь файлом с адресом сервисного аккаунта как с читателем.</p><pre class="code">GOOGLE_DRIVE_FILE_ID=1XCZbSDWBLjf-X5lqvBaLQhvb3R0eRSRr\nGOOGLE_APPLICATION_CREDENTIALS=C:/Zuma_CashFlow/secrets/drive.json</pre><p class="small muted">Добавьте значения в config.env на сервере, установите requirements-drive.txt и перезапустите сайт. После этого кнопка «Обновить из Drive» импортирует новую версию по запросу. Фоновое расписание не включено автоматически.</p><div class="form-actions"><button class="btn primary" data-action="close-modal">Понятно</button></div>`)}
/* События */
document.addEventListener('click',async e=>{const b=e.target.closest('button[data-page],button[data-action],a[data-page]');if(!b)return;e.preventDefault();if(b.dataset.page){if($('modal').open)$('modal').close();return navigate(b.dataset.page)}const a=b.dataset.action,id=Number(b.dataset.id);try{
 switch(a){case 'close-modal':$('modal').close();break;case 'refresh':await bootstrap();await renderPage();toast('Данные обновлены');break;case 'logout':await post('/api/logout');showLogin();break;case 'days':S.days=Number(b.dataset.days);await renderPage();break;
 case 'new-account':newAccount();break;case 'new-request':await newRequest();break;case 'new-receipt':await newReceipt();break;case 'new-ledger':await newLedger();break;case 'pay':await newLedger(S.requests.find(r=>r.id===id));break;case 'receive':await newLedger(S.receipts.find(r=>r.id===id),true);break;case 'approve':approveRequest(S.requests.find(r=>r.id===id));break;case 'request-detail':requestDetail(S.requests.find(r=>r.id===id));break;
 case 'submit-request':await post(`/api/requests/${id}/decision`,{action:'submit'});await renderPage();toast('Заявка отправлена на согласование');break;
 case 'reschedule':{let r=S.requests.find(r=>r.id===id);form('Перенос · '+r.number,inp('date','Новая дата','date',r.date,'required')+area('note','Причина переноса','','required minlength="10" maxlength="2000"'),d=>post(`/api/requests/${id}/decision`,{...d,action:'reschedule'}),{note:'Утверждение будет снято. Заявка вернётся на согласование и временно выйдет из календаря и резерва лимита.'});break}
 case 'reverse':{let t=S.ledger.find(x=>x.id===id);form('Сторно операции #'+id,area('reason','Причина исправления','','required minlength="10" maxlength="1000"'),d=>post(`/api/ledger/${id}/reverse`,d),{note:`Будет создана обратная запись датой ${t.date}. Исходная операция останется в базе. Связанная заявка или ожидание поступления откроется снова. Это исправление учёта, не возврат денег через банк.`,button:'Выполнить сторно'});break}
 case 'budget':budgetForm(id);break;case 'reserve':form('Минимальный резерв · '+S.currency,inp('amount','Минимальный запас денег','number',S.dashboard?.reserve||'0','required min="0" step="0.01"'),d=>post('/api/reserve',{...d,currency:S.currency}),{note:'Резерв влияет на предупреждение о ликвидности. Он не является фактическим расходом и не списывает деньги.'});break;
 case 'new-category':form('Новая статья',inp('name','Название статьи','text','','required minlength="2" maxlength="160"')+sel('activity','Вид деятельности',[['operating','Операционная'],['investing','Инвестиционная'],['financing','Финансовая']],'operating'),d=>post('/api/categories',d));break;
 case 'filter':S.filter=b.dataset.filter;await renderPage();break;case 'model-tab':S.modelKey=b.dataset.key;await renderPage();break;case 'model-mode':S.modelMode=b.dataset.mode;await renderPage();break;case 'upload-model':uploadModel();break;case 'drive-sync':if(!S.model?.drive_configured)driveInfo();else{b.disabled=true;const r=await post('/api/model/drive-sync');S.modelVersion=r.id;await renderPage();toast(r.created?'Новая версия импортирована':'Файл не изменился; дубликат не создан')}break;
 case 'model-errors':{let sp=S.model.snapshot;modal('Диагностика исходного Excel',`<div class="form-note">Приведены первые 250 ошибок и ячеек без сохранённого результата из проверенных листов. Ничего не заменено нулями.</div><div class="small muted">Ошибок: ${sp.error_count}; без результата: ${sp.missing_cache_count}</div><div class="table-scroll"><table class="data-table"><thead><tr><th>Ячейка</th><th>Ошибка</th></tr></thead><tbody>${sp.errors.map(x=>`<tr><td>${esc(x.sheet+'!'+x.cell)}</td><td class="out">${esc(x.error)}</td></tr>`).join('')}</tbody></table></div>${sp.missing_cache.length?'<p class="small muted" style="margin-top:15px">Нет результата: '+esc(sp.missing_cache.join(', '))+'</p>':''}`);break}
 case 'new-user':userForm();break;case 'edit-user':userForm(S.users.find(u=>u.id===id));break;case 'password':form('Изменить пароль',inp('old_password','Текущий пароль','password','','required autocomplete="current-password" maxlength="128"')+inp('new_password','Новый пароль','password','','required minlength="12" maxlength="128" autocomplete="new-password"'),async d=>{await post('/api/password',d);showLogin()},{note:'После изменения все сессии будут завершены. Войдите с новым паролем.'});break;case 'print':window.print();break;
 }
 }catch(err){toast(err.message,true)}finally{b.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='requestSearch'){S.search=e.target.value;$('requestList').innerHTML=requestCards()}});
document.addEventListener('change',async e=>{try{if(e.target.id==='currency'){S.currency=e.target.value;await renderPage()}if(e.target.id==='budgetMonth'){S.budgetMonth=e.target.value;await renderPage()}if(e.target.id==='modelVersion'){S.modelVersion=Number(e.target.value);await renderPage()}if(e.target.id==='reportYear'){S.reportYear=Number(e.target.value);await renderPage()}}catch(err){toast(err.message,true)}});
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;$('loginError').textContent='';try{const data=Object.fromEntries(new FormData(e.target));const r=await post('/api/login',data);S.user=r.user;S.csrf=r.csrf;e.target.elements.password.value='';await enter()}catch(err){$('loginError').textContent=err.message}finally{b.disabled=false}});
$('revealPassword').addEventListener('click',()=>{let f=$('loginForm').elements.password;f.type=f.type==='password'?'text':'password'});
window.addEventListener('hashchange',()=>{if(S.user)navigate(location.hash.slice(1))});
hydrateIcons();start();
